#!/usr/bin/env python3
"""Reconstruct source files for the isolated GitHub Actions research run."""
from pathlib import Path
import base64, gzip

FILES = {
    'uvb76_pipeline.py': '',
    'tests/test_uvb76_pipeline.py': '',
    'requirements.txt': 'H4sIAAAAAAAC/x2OSw7DIAxE99ylFr9GzcKHIQ1VkfgVjNrcvobl03je+PBuUHiN2MuoFtGCsmBE/KWIuIEELZKjGgvFcCAaUBIeIo9UL0QNBu6iuny6PolZ1Mu1Vr6MituSmd4l305HnofiPNs5qKWTFM1/hu+0ykazqz/DFCtQ23IRp4j7+uMPAPE7m6sAAAA=',
}

for name, payload in FILES.items():
    path = Path(name)
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_bytes(gzip.decompress(base64.b64decode(payload)))
    print(f"wrote {path} ({path.stat().st_size} bytes)")
